-- Despesas do grupo de comprovantes (WhatsApp), 29/09 a 13/10/2026
-- 81 despesas, R$ 331.137,10. Lidas dos comprovantes encaminhados no grupo
-- "Compravnates outubro". Os de 25/09 a 29/09 de manhã que já tinham sido
-- importados (importacao-comprovantes.sql) ficaram de fora, assim como a
-- transferência para a conta do BNB (é da própria empresa) e um comprovante repetido.
-- Cole tudo no SQL Editor do Supabase e clique em Run. Pode rodar de novo: não duplica.
-- Para desfazer: delete from public.despesas where nota like 'Grupo Compravnates outubro%';
-- ════════════════════════════════════════════════════════════════════════

begin;

-- Centro de custo da compra e revenda de laranja de outros produtores.
values ('00000000-0000-4000-8000-000000000008', 'Laranja de terceiros', 'agricola', 't', true,
        'Compra e revenda de laranja de outros produtores')
on conflict (id) do nothing;

-- Comprovante de 29/09 que tinha entrado sem legenda: a legenda veio logo depois da foto.
update public.despesas set tipo = 'Quadros escritório', descricao = 'Quadros escritório'
 where id = 'b13f196a-f380-5fc6-ab52-33ab28fd89f7' and tipo = 'Sem legenda no grupo';


commit;
